 "content": "from collections import Counter, defaultdict


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen
                            and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append((color, cells))
    return components


def _shape(cells):
    """Canonical polyomino under rotations and reflections."""
    variants = []
    for reflect in (1, -1):
        for turns in range(4):
            pts = []
            for r, c in cells:
                x, y = r, c * reflect
                for _ in range(turns):
                    x, y = y, -x
                pts.append((x, y))
            minx = min(x for x, y in pts)
            miny = min(y for x, y in pts)
            variants.append(tuple(sorted((x - minx, y - miny) for x, y in pts)))
    return min(variants)


def _marker_score(cells):
    """Recognize the long straight/L-shaped indicator component."""
    rows = Counter(r for r, c in cells)
    cols = Counter(c for r, c in cells)
    maxrun = max(max(rows.values()), max(cols.values()))
    # A bent indicator consists of two perpendicular arms sharing a corner.
    # Test each possible corner and check that all cells lie on its two arms.
    l_score = 0
    for r0, c0 in cells:
        horizontal = [c for r, c in cells if r == r0]
        vertical = [r for r, c in cells if c == c0]
        if not horizontal or not vertical:
            continue
        hmin, hmax = min(horizontal), max(horizontal)
        vmin, vmax = min(vertical), max(vertical)
        union = {(r0, c) for c in range(hmin, hmax + 1)} | {(r, c0) for r in range(vmin, vmax + 1)}
        if set(cells) == union and (r0, c0) in cells:
            a, b = hmax - hmin + 1, vmax - vmin + 1
            if min(a, b) >= 3:
                l_score = max(l_score, a + b)
    if l_score:
        return (2, l_score, len(cells))
    # Some tasks use a single long line as the indicator.
    if len(cells) >= 5 and (len(rows) == 1 or len(cols) == 1):
        return (1, maxrun, len(cells))
    return (0, 0, 0)


def _distance(cells_a, cells_b):
    return min(abs(r1-r2) + abs(c1-c2)
               for r1, c1 in cells_a for r2, c2 in cells_b)


def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    components = _components(grid, background)

    # The long L (or, in one variant, straight line) supplies the output color.
    marker = max(components, key=lambda item: _marker_score(item[1]))
    marker_color, marker_cells = marker
    if _marker_score(marker_cells)[0] == 0:
        return out

    groups = defaultdict(list)
    for color, cells in components:
        if cells is marker_cells or len(cells) < 3:
            continue
        key = _shape(cells)
        # Ignore straight bars: the repeated object is a nontrivial shape.
        rs = {r for r, c in cells}
        cs = {c for r, c in cells}
        if len(rs) == 1 or len(cs) == 1:
            continue
        groups[key].append((color, cells))

    duplicate_groups = [items for items in groups.values() if len(items) >= 2]
    if not duplicate_groups:
        return out
    # The intended repeated object is the largest non-line polyomino pair.
    pair_group = max(duplicate_groups, key=lambda items: (len(items[0][1]), len(items)))
    # Recolor the copy farther from the indicator; the nearby copy is the exemplar.
    target = max(pair_group, key=lambda item: _distance(item[1], marker_cells))
    for r, c in target[1]:
        out[r][c] = marker_color
    return out


if __name__ == '__main__':
    pass
